package cn.paletale.companion;
import com.google.gson.*;
import com.sun.net.httpserver.HttpServer;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.gui.components.Button;
final class WorldInteractionClientTest {
 static void require(boolean ok,String label){if(!ok)throw new AssertionError(label);}
 static Object field(Object o,String key){return WorldClientGameTest.field(o,key);}
 static long buttons(net.minecraft.client.gui.screens.Screen screen,String label){return screen.children().stream().filter(b->b instanceof Button a&&a.getMessage().getString().equals(label)).count();}
 static void run(ClientGameTestContext context)throws Exception{
  var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var workers=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor();server.setExecutor(workers);var marketCalls=new AtomicInteger();var worldCalls=new AtomicInteger();var writes=new AtomicInteger();var slow=new AtomicBoolean();
  server.createContext("/api/",ex->{String path=ex.getRequestURI().getPath(),body="{}";int status=200;if(!ex.getRequestMethod().equals("GET"))writes.incrementAndGet();
   if(path.equals("/api/mcmod/market")){marketCalls.incrementAndGet();if(slow.get())try{Thread.sleep(400);}catch(InterruptedException ignored){}body=WorldClientGameTest.MarketRegressionTestBody.VALUE;}
   else if(path.equals("/api/mcmod/world/catalog")){worldCalls.incrementAndGet();body=payload().toString();}
   else if(path.equals("/api/mcmod/world/online")){var root=new JsonObject();root.addProperty("version",1);root.addProperty("total",24);var players=new JsonArray();for(int i=0;i<24;i++){var p=new JsonObject();p.addProperty("name","Player"+i);p.addProperty("eligible",i!=23);players.add(p);}root.add("players",players);body=root.toString();}
   else if(path.equals("/api/mcmod/world/players/ShopKeeper"))body="{\"value\":{\"balance\":120,\"last_seen\":\"当前\"}}";
   else if(path.startsWith("/api/smc-world/players/")){byte[] png=Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAgAAAAICAYAAADED76LAAAAFklEQVR4nGP4n5Dw//8JIMZBM4wMBQAlN7yBcc2FBwAAAABJRU5ErkJggg==");ex.getResponseHeaders().set("Content-Type","image/png");ex.sendResponseHeaders(200,png.length);try(var out=ex.getResponseBody()){out.write(png);}return;}
   else status=404;
   byte[] bytes=body.getBytes(StandardCharsets.UTF_8);ex.getResponseHeaders().set("Content-Type","application/json");ex.sendResponseHeaders(status,bytes.length);try(var out=ex.getResponseBody()){out.write(bytes);}
  });server.start();var api=new MarketApi(URI.create("http://127.0.0.1:"+server.getAddress().getPort()));double old=ModSettings.uiScale();
  try{
   context.runOnClient(c->{ModSettings.setUiScale(1);c.getWindow().setWindowed(1920,1080);c.options.guiScale().set(2);c.resizeDisplay();c.setScreen(new MarketScreen(null,api));});
   context.waitFor(c->c.screen instanceof MarketScreen s&&!s.isLoading()&&s.result()!=null,600);int calls=marketCalls.get();
   context.runOnClient(c->{c.setScreen(new MarketScreen(null,api));require(((MarketScreen)c.screen).result()!=null,"Returning to ads immediately shows the snapshot");});context.waitTicks(3);require(marketCalls.get()==calls,"Warm market re-entry does not download again");
   context.runOnClient(c->{var cache=(WorldCatalogCache)staticField(MarketApi.class,"PUBLIC");for(var entry:((Map<?,?>)field(cache,"entries")).values())WorldClientGameTest.field(entry,"at",System.currentTimeMillis()-1800000);c.setScreen(new MarketScreen(null,api));});context.waitFor(c->!((MarketScreen)c.screen).isLoading(),600);require(marketCalls.get()==calls,"A half-hour return still uses the hourly cache");context.runOnClient(c->require((Long)field(c.screen,"nextRefresh")-System.currentTimeMillis()<1801000,"Re-entry does not extend the original cache deadline"));
   context.runOnClient(c->{var cache=(WorldCatalogCache)staticField(MarketApi.class,"PUBLIC");for(var entry:((Map<?,?>)field(cache,"entries")).values())WorldClientGameTest.field(entry,"at",System.currentTimeMillis()-3600001);});slow.set(true);
   context.runOnClient(c->{c.setScreen(new MarketScreen(null,api));require(((MarketScreen)c.screen).result()!=null&&((MarketScreen)c.screen).isLoading(),"Stale ad rows remain visible during background revalidation");require(c.screen.children().stream().anyMatch(b->b instanceof MarketCardButton),"Refresh keeps actual clickable market cards");});
   context.waitFor(c->!((MarketScreen)c.screen).isLoading(),600);require(marketCalls.get()==calls+1,"Stale cache refreshes exactly once");context.takeScreenshot("smc-v19-market-cache");
   context.clickScreenButton("手动刷新");context.runOnClient(c->require(((MarketScreen)c.screen).result()!=null,"Manual refresh retains the existing ad rows"));context.waitFor(c->!((MarketScreen)c.screen).isLoading(),600);require(marketCalls.get()==calls+2,"Manual market refresh bypasses fresh hourly cache");
   context.runOnClient(c->c.setScreen(new WorldEntityScreen(null,api,"player","ShopKeeper")));context.waitFor(c->field(c.screen,"catalog")!=null&&!((Boolean)field(c.screen,"loading")),600);int before=worldCalls.get();
   context.runOnClient(c->{require(buttons(c.screen,"上线")==0&&buttons(c.screen,"下线")==0&&buttons(c.screen,"已上线")==0,"Mod exposes no visibility management controls");require(c.screen.children().stream().filter(b->b instanceof Button button&&button.getMessage().getString().equals("导航")).allMatch(b->"compass".equals(field(b,"icon"))),"Every shop navigation button carries a compass");require(buttons(c.screen,"测试港")==1&&buttons(c.screen,"测试国家")==0,"Transport has a link and redundant nation column is removed");});
   context.clickScreenButton("领地");context.runOnClient(c->{require(!(Boolean)field(c.screen,"loading"),"Local projection switches without querying");require(buttons(c.screen,"ShopKeeper")==0&&buttons(c.screen,"导航")==0,"Old shop widgets disappear immediately on land tab");});context.clickScreenButton("商店");require(worldCalls.get()==before,"Switching land/shop tabs reuses catalog");
   context.waitFor(c->((Map<?,?>)field(MarketImages.INSTANCE,"images")).containsKey(WorldPortrait.path("ShopKeeper")),600);
   var hover=context.computeOnClient(c->{var s=(WindowScreen)c.screen;return new int[]{s.winX+210,s.winY+125};});context.getInput().setCursorPos(hover[0],hover[1]);context.waitTicks(12);context.takeScreenshot("smc-v18-player-table-avatar-no-tooltip");
   context.clickScreenButton("测试港");context.waitFor(c->field(c.screen,"catalog")!=null&&!((Boolean)field(c.screen,"loading")),600);context.runOnClient(c->require(field(c.screen,"type").equals("traffic")&&field(c.screen,"key").equals("hub:1"),"Transport opens its corresponding scope"));context.runOnClient(c->c.screen.onClose());
   context.clickScreenButton("国籍");context.clickScreenButton("测试国家");context.waitFor(c->field(c.screen,"catalog")!=null&&!((Boolean)field(c.screen,"loading")),600);context.runOnClient(c->require(field(c.screen,"type").equals("nation"),"Nation opens its corresponding scope"));context.clickScreenButton("玩家");context.waitFor(c->!((Boolean)field(c.screen,"loading"))&&field(c.screen,"catalog")!=null,600);context.runOnClient(c->require(c.screen.children().stream().anyMatch(b->b instanceof ArchiveCardButton),"Scope player lists reuse archive cards"));context.takeScreenshot("smc-v18-scope-player-grid");
   context.runOnClient(c->c.setScreen(new WorldEntityScreen(null,api,"online","all")));context.waitFor(c->field(c.screen,"catalog")!=null&&!((Boolean)field(c.screen,"loading")),600);context.runOnClient(c->{require(c.screen.children().stream().filter(b->b instanceof ArchiveCardButton).count()>=12,"Online list uses a dense archive avatar grid");require(c.screen.children().stream().filter(b->b instanceof ArchiveCardButton card&&card.entry.name().equals("Player23")).allMatch(b->!((Button)b).active),"Unknown online names do not become queryable profiles");});context.waitFor(c->((Map<?,?>)field(MarketImages.INSTANCE,"images")).containsKey(WorldPortrait.path("Player0")),600);context.waitTicks(6);context.takeScreenshot("smc-v18-online-player-grid");
   context.runOnClient(c->{c.getWindow().setWindowed(1024,768);c.options.guiScale().set(3);c.resizeDisplay();});context.takeScreenshot("smc-v18-online-compact");
   require(writes.get()==0,"Browsing scopes and cards never changes listing state");
  }finally{context.runOnClient(c->{ModSettings.setUiScale(old);c.setScreen(null);});server.stop(0);workers.shutdownNow();}
 }
 static Object staticField(Class<?> type,String key){try{var f=type.getDeclaredField(key);f.setAccessible(true);return f.get(null);}catch(Exception e){throw new AssertionError(e);}}
 static JsonObject payload(){var root=new JsonObject();root.addProperty("version",1);root.addProperty("total",1);root.addProperty("scopeTotal",1);var shops=new JsonArray();var shop=new JsonObject();for(String[] e:new String[][]{{"owner","ShopKeeper"},{"itemName","钻石"},{"mode","sell"},{"world","worlds:spawn"}})shop.addProperty(e[0],e[1]);shop.addProperty("quantity",64);shop.addProperty("sellPrice",100);shop.addProperty("x",30);shop.addProperty("y",64);shop.addProperty("z",30);var lands=new JsonArray();var land=new JsonObject();land.addProperty("id","测试国家|测试领地");land.addProperty("key","测试国家|测试领地");land.addProperty("name","测试领地");land.addProperty("nation","测试国家");land.addProperty("role","成员");lands.add(land);shop.add("lands",lands);var routes=new JsonArray();var route=new JsonObject();route.addProperty("key","hub:1");route.addProperty("name","测试港");routes.add(route);shop.add("routes",routes);shops.add(shop);root.add("shops",shops);root.add("memberships",lands);var scope=new JsonObject();scope.addProperty("title","测试区域");scope.addProperty("landCount",1);scope.addProperty("playerCount",1);scope.add("stats",new JsonObject());scope.add("lands",lands);scope.add("transport",routes);var players=new JsonArray();var player=new JsonObject();player.addProperty("name","ShopKeeper");players.add(player);scope.add("players",players);root.add("scope",scope);return root;}
}
